  },
};

const textContent = $('Parse Text').item.json.textContent;
const item = $('Parse Text').item.json.item;
const tenantId = $('Parse Text').item.json.tenant_id || item.owner_ref;
return { json: { payload: {
  p_organization_id: tenantId,
  p_content_item_id: item.id,
  p_expected_current_state: 'idea',
  p_next_state: 'research_ready',
  p_actor_ref: 'agent_content_creator',
  p_idempotency_key: 'trans_' + $execution.id + '_research',
  p_stage_payload: { artifacts: [{ artifact_key: 'res_' + $execution.id + '_' + item.id.replace(/-/g, '_'), artifact_type: 'viral_research_packet', content: textContent.agent_1_research_packet }] }
}}};

const parsed = $('Parse Text').first().json;
const visual = $('Extract Visual').first().json;
const captionNode = $('Extract Caption').first().json;
const webhookItem = $('Webhook Trigger').first().json.body || $('Webhook Trigger').first().json;
const threadId = webhookItem.threadId;

const research = parsed.textContent?.agent_1_research_packet || '';
const caption =
  parsed.textContent?.agent_2_publish_ready_caption ||
  captionNode.artifacts?.caption ||
  '';
const imageUrl = $('Map R2 URL').item.json.r2_url || '';

const outboxId = $('Poll Image Status').first().json.outbox_id || '';
const taskId = $('AI Broker (Image)').item.json.taskId;
const providerCode = $('AI Broker (Image)').item.json.provider;
const usageId = $('AI Broker (Image)').item.json.usage_id;
const modelCode = $('AI Broker (Image)').item.json.model;

const bodyStr = `**Nội dung đã được tạo thành công (QA_ready)**\n\n![Generated Image](${imageUrl})\n\n**Caption:**\n${caption}\n\n**Research Packet:**\n\`\`\`json\n${JSON.stringify(research, null, 2)}\n\`\`\``;

return {
  json: {
    thread_id: threadId,
    organization_id: parsed.organization_id || visual.organization_id || '',
    sender: 'agent',
    intent_type: 'image_generation_completed',
    body: bodyStr,
    metadata: {
      task_id: taskId,
      provider_code: providerCode,
      model_code: modelCode,
      usage_id: usageId,
      outbox_id: outboxId,
      result_image_url: imageUrl
    }
  }
};

