={{ (() => {
  const cfg = $('Fetch Tenant AI Config').first().json;
  const prompt = $('Parse Text').first().json.textContent?.agent_3_image_prompt;
  const imageBinding = cfg.provider_bindings?.image;
  if (!imageBinding?.provider_code || !imageBinding?.model_code) {
    throw new Error('IMAGE_LANE_BINDING_MISSING');
  }
  if (!prompt || !String(prompt).trim()) {
    throw new Error('IMAGE_PROMPT_MISSING');
  }
  return {
    provider: imageBinding.provider_code,
    model: imageBinding.model_code,
    async: true,
    prompt,
    n: 1,
    size: '1024x1024',
    tenant_id: $('Parse Text').first().json.tenant_id,
    lane_key: 'image',
    tenant_binding_id: cfg.tenant_binding_id || ''
  };
})() }}

