const responseText = $input.first().json.choices?.[0]?.message?.content || '{}';
const item = $('Format Prompt').item.json.item;
const tenant_id = $('Format Prompt').item.json.tenant_id;
let parsed = {};
try {
  parsed = JSON.parse(responseText);
} catch(e) {
  throw new Error('AI Response was not valid JSON');
}

const researchPacket = typeof parsed.agent_1_research_packet === 'string' ? parsed.agent_1_research_packet.trim() : '';
const captionPacket = typeof parsed.agent_2_publish_ready_caption === 'string' ? parsed.agent_2_publish_ready_caption.trim() : '';
const imagePrompt = typeof parsed.agent_3_image_prompt === 'string' ? parsed.agent_3_image_prompt.trim() : '';
if (!researchPacket) {
  throw new Error('RESEARCH_PACKET_MISSING');
}
if (!captionPacket) {
  throw new Error('CAPTION_PACKET_MISSING');
}
if (!imagePrompt) {
  throw new Error('IMAGE_PROMPT_MISSING');
}

return { 
  json: { 
    id: item.id, 
    organization_id: item.organization_id,
    tenant_id: tenant_id,
    textContent: {
      agent_1_research_packet: researchPacket,
      agent_2_publish_ready_caption: captionPacket,
      agent_3_image_prompt: imagePrompt
    },
    item: item
  } 
};

const ideaItem = $('Get Item (Webhook)').item.json[0] || $('Get Item (Webhook)').item.json;
const govData = $('Fetch Governance Registry').item.json.data;

if (!ideaItem) {
  throw new Error('CONTENT_ITEM_NOT_FOUND');
}

// Find agents
const agent1 = govData.agents.find(a => a.role_id === 'marketing_agent_1_viral_research_angle');
const agent2 = govData.agents.find(a => a.role_id === 'marketing_agent_2_social_caption_architect');
const agent3 = govData.agents.find(a => a.role_id === 'marketing_agent_3_image_prompt_architect');

if (!agent1 || !agent2 || !agent3) {
  throw new Error('MARKETING_AGENT_REGISTRY_INCOMPLETE');
}

if (!agent1.capability_boundary || !agent2.capability_boundary || !agent3.capability_boundary) {
  throw new Error('MARKETING_AGENT_CAPABILITY_BOUNDARY_MISSING');
}

const prompt = `You are an orchestration of 3 specialized AI Marketing Agents working in sequence.
You MUST respect the capabilities (MUST) and strictly avoid the prohibitions (MUST NOT) of each agent.
The governance rules are currently in DRAFT_METADATA_ONLY mode.

[AGENT 1: VIRAL RESEARCH ANGLE]
MUST: ${agent1.capability_boundary.must.join(', ')}
MUST NOT: ${agent1.capability_boundary.must_not.join(', ')}

[AGENT 2: SOCIAL CAPTION ARCHITECT]
MUST: ${agent2.capability_boundary.must.join(', ')}
MUST NOT: ${agent2.capability_boundary.must_not.join(', ')}

[AGENT 3: IMAGE PROMPT ARCHITECT]
MUST: ${agent3.capability_boundary.must.join(', ')}
MUST NOT: ${agent3.capability_boundary.must_not.join(', ')}

---
Idea Title: ${ideaItem.title}
Brief: ${ideaItem.brief || 'No brief provided.'}

IMPORTANT LANGUAGE & CONTEXT INSTRUCTION:
- You MUST write the "agent_1_research_packet" and "agent_2_publish_ready_caption" entirely in Vietnamese (Tiếng Việt).
- CRITICAL COPYWRITING CONSTRAINT: For "agent_2_publish_ready_caption", you MUST act as a modern Social Media Copywriter. Do NOT write generic, robotic, or short/abrupt text. You MUST use a highly engaging hook (first sentence) to grab attention. You MUST use line breaks (xuống dòng) effectively for readability, strategically insert relevant emojis, and write in an engaging, interactive tone that encourages comments and shares. End with a clear Call-to-Action.
- The "agent_3_image_prompt" MUST remain in English.
- The target audience is strictly Vietnamese. For "agent_3_image_prompt", you MUST explicitly instruct the image generator to depict Vietnamese people (e.g., "Vietnamese characters", "Vietnamese youth", "Asian descent in Vietnam") and Vietnamese contexts/settings.
- CRITICAL VISUAL CONSTRAINT: For "agent_3_image_prompt", you MUST act as a Gen-Z Viral Art Director. You MUST explicitly instruct the image generator to use "dynamic camera angles, cinematic lighting, vibrant neon/pastel colors, trendy streetwear/fashion, and highly stylized modern aesthetics (e.g., 3D render, pop-art, cyberpunk, or high-end magazine editorial)". DO NOT use "neutral lighting, natural daylight, or standard stock photo composition". Make the image look incredibly HOT, TRENDY, and VIRAL.
- TEXT RENDERING CONSTRAINT: The image generator CAN render text. You SHOULD include a short, punchy Vietnamese catchphrase (maximum 1 to 4 words) to be rendered directly into the image. You MUST explicitly write the text in quotes in the prompt (e.g., "The words 'Bão Sale' written in bold 3D neon typography in the background"). Keep the text extremely short to ensure spell-check accuracy.

Respond in STRICT JSON format, fulfilling the exact outputs required by each agent without crossing boundaries:
{
  "agent_1_research_packet": "Nội dung phân tích viral và pain points bằng Tiếng Việt...",
  "agent_2_publish_ready_caption": "Nội dung caption bài đăng bằng Tiếng Việt...",
  "agent_3_image_prompt": "A highly detailed image prompt in English..."
}
`;

return { json: { prompt: prompt, item: ideaItem, tenant_id: ideaItem.organization_id, organization_id: ideaItem.organization_id } };
